function wireTap(handler, { capacity = 1024 } = {}) {
  const queue = [], pending = [];
  let dropped = 0;
  const tap = {
    get dropped() { return dropped; },                     // visible loss counter
    async *[Symbol.asyncIterator]() {
      while (queue.length) yield queue.shift();
      while (true) yield await new Promise((r) => pending.push(r));
    },
  };
  return {
    tap,
    route(message) {
      const copy = structuredClone(message);               // snapshot, not a reference
      const waiter = pending.shift();
      if (waiter) waiter(copy);                            // analyzer resumes after route() returns
      else {
        if (queue.length >= capacity) { queue.shift(); dropped++; }  // drop-oldest, counted
        queue.push(copy);
      }
      return handler(message);                             // original to the primary, unchanged
    },
  };
}
